      [{ rows: [[2, 1, 3, 1]], removeButton: { width: 'auto' } }],
      [{ rows: [[2, 1, 3, 1]], removeButton: { ownRow: true } }],
    ],
    items: [defaultItems],
    addButtonText: ['Add item (grid)'],
    removeButtonText: ['Remove item (grid)'],
