  {
    definition: [validationDefinitions],
    i18nStrings: [{ errorIconAriaLabel: 'Error', warningIconAriaLabel: 'Warning' }],
    items: [defaultItems],
    addButtonText: ['Add item'],
    removeButtonText: ['Remove item'],
  },
