      <AttributeEditor<Tag>
        {...labelProps}
        additionalInfo={additionalInfo}
        items={items}
        definition={[...definition, ...definition]}
        customRowActions={({ breakpoint, item, itemIndex }) => {
          const clickHandler = () => {
            onRemoveButtonClick({ detail: { itemIndex } });
          };
          const ariaLabel = `Remove ${item.key}`;
          if (breakpoint === 'xl') {
            return <Button iconName="remove" variant="icon" ariaLabel={ariaLabel} onClick={clickHandler} />;
          }
          return (
            <Button ariaLabel={ariaLabel} onClick={clickHandler}>
              Remove
            </Button>
          );
        }}
        onAddButtonClick={onAddButtonClick}
        onRemoveButtonClick={onRemoveButtonClick}
        gridLayout={[
          {
            breakpoint: 'xl',
            rows: [[4, 1, 2, 2]],
            removeButton: {
              width: 'auto',
            },
          },
          {
            breakpoint: 'l',
            rows: [[4, 1, 2, 2]],
            removeButton: {
              ownRow: true,
            },
          },
          {
            breakpoint: 's',
            rows: [
              [3, 1],
              [2, 2],
            ],
          },
          {
            rows: [[1], [1], [1], [1]],
          },
        ]}
      />
    </Box>
  );
}

